// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// CreateArchive Prepare a ZIP archive of files and folders
	// (POST /files/archives)
	CreateArchive(ctx context.Context, request CreateArchiveRequestObject) (CreateArchiveResponseObject, error)
	// DownloadArchive Download a prepared ZIP archive
	// (GET /files/archives/{id})
	DownloadArchive(ctx context.Context, request DownloadArchiveRequestObject) (DownloadArchiveResponseObject, error)
	// DownloadFile Download a file
	// (GET /files/content)
	DownloadFile(ctx context.Context, request DownloadFileRequestObject) (DownloadFileResponseObject, error)
	// UploadFile Upload a file (simple, streamed)
	// (PUT /files/content)
	UploadFile(ctx context.Context, request UploadFileRequestObject) (UploadFileResponseObject, error)
	// CreateFolder Create a folder
	// (POST /files/folders)
	CreateFolder(ctx context.Context, request CreateFolderRequestObject) (CreateFolderResponseObject, error)
	// DeleteItem Delete a file or folder
	// (DELETE /files/items)
	DeleteItem(ctx context.Context, request DeleteItemRequestObject) (DeleteItemResponseObject, error)
	// GetItems List a folder, or get the details of a file
	// (GET /files/items)
	GetItems(ctx context.Context, request GetItemsRequestObject) (GetItemsResponseObject, error)
	// CopyItem Copy a file or folder
	// (POST /files/operations/copy)
	CopyItem(ctx context.Context, request CopyItemRequestObject) (CopyItemResponseObject, error)
	// MoveItem Move a file or folder
	// (POST /files/operations/move)
	MoveItem(ctx context.Context, request MoveItemRequestObject) (MoveItemResponseObject, error)
	// RenameItem Rename a file or folder
	// (POST /files/operations/rename)
	RenameItem(ctx context.Context, request RenameItemRequestObject) (RenameItemResponseObject, error)
	// GetHealth Server health and startup checks
	// (GET /system/health)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// CreateArchive operation middleware
func (sh *strictHandler) CreateArchive(w http.ResponseWriter, r *http.Request) {
	var request CreateArchiveRequestObject

	var body CreateArchiveJSONRequestBody
	if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
		sh.options.RequestErrorHandlerFunc(w, r, fmt.Errorf("can't decode JSON body: %w", err))
		return
	}
	request.Body = &body

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.CreateArchive(ctx, request.(CreateArchiveRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "CreateArchive")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(CreateArchiveResponseObject); ok {
		if err := validResponse.VisitCreateArchiveResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

